let ROOM='mut';
function mergeStatic(root){root.updateMatrixWorld(true);const by=new Map(),kill=[];
 root.traverse(o=>{if(!o.isMesh||!o.visible||o.material.transparent)return;const k=o.material.uuid;if(!by.has(k))by.set(k,{m:o.material,list:[]});by.get(k).list.push(o);kill.push(o)});
 by.forEach(({m,list})=>{let n=0;const parts=list.map(o=>{let g=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();g.applyMatrix4(o.matrixWorld);n+=g.attributes.position.count;return g});
  const P=new Float32Array(n*3),N=new Float32Array(n*3),U=new Float32Array(n*2);let p=0;
  parts.forEach(g=>{const c=g.attributes.position.count;P.set(g.attributes.position.array,p*3);if(!g.attributes.normal)g.computeVertexNormals();N.set(g.attributes.normal.array,p*3);if(g.attributes.uv)U.set(g.attributes.uv.array,p*2);p+=c;g.dispose()});
  const bg=new THREE.BufferGeometry();bg.setAttribute('position',new THREE.BufferAttribute(P,3));bg.setAttribute('normal',new THREE.BufferAttribute(N,3));bg.setAttribute('uv',new THREE.BufferAttribute(U,2));bg.computeBoundingSphere();
  const mm=new THREE.Mesh(bg,m);mm.castShadow=mm.receiveShadow=true;G.add(mm)});
 kill.forEach(o=>{o.parent.remove(o);o.geometry.dispose()})}
