 for(let i=0;i<d.length;i++){l=(l+0.02*(Math.random()*2-1))/1.02;d[i]=l*3.5}const n=a.createBufferSource();n.buffer=nb;const lp=a.createBiquadFilter();lp.type='lowpass';lp.frequency.value=140;
